def primitive_map(x,path='$'):
    out=[dict(path=path,type='object' if isinstance(x,dict) else 'array' if isinstance(x,list) else 'boolean' if isinstance(x,bool) else 'integer' if isinstance(x,int) else 'string',keys=list(x) if isinstance(x,dict) else None,length=len(x) if isinstance(x,list) else None)]
    if isinstance(x,dict):
        for k,v in x.items():out+=primitive_map(v,path+'.'+k)
    elif isinstance(x,list):
        for i,v in enumerate(x):out+=primitive_map(v,path+'['+str(i)+']')
    return out
